daa-c2-t01.pseudocode:
DAC(P)
  if small(P) then return Solve(P)
  divide P into P1..Pk
  for each Pi: Si ← DAC(Pi)
  return Combine(S1..Sk)

daa-c3-t01.pseudocode:
Greedy(C)
  S ← ∅
  while C not empty and S not complete do
    x ← Select(C); C ← C − {x}
    if Feasible(S ∪ {x}) then S ← S ∪ {x}
  return S
